package com.example.shortener.validation;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** AC: links to known third-party URL shorteners are rejected, so a short link cannot hide its real destination. */
class UrlValidatorDenylistTest {

    private final UrlValidator validator = new UrlValidator("sho.rt", false);

    @Test
    void rejectsKnownShorteners() {
        for (String url : List.of("https://bit.ly/3abc", "http://tinyurl.com/x", "https://t.co/abc",
                "https://www.bit.ly/abc", "https://BIT.LY/abc", "https://is.gd/q")) {
            assertThatThrownBy(() -> validator.validate(url))
                    .as(url)
                    .isInstanceOf(InvalidUrlException.class)
                    .hasMessageContaining("shorteners");
        }
    }

    @Test
    void stillAcceptsNormalDomains() {
        for (String url : List.of("https://example.com", "https://notbit.ly.example.com/", "https://mybit.ly/", "https://t.company.com/")) {
            assertThat(validator.validate(url)).as(url).isEqualTo(url);
        }
    }
}
